export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [600000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[]], details: {}, terminate: false };
    },
  });
}

export default function (pi) {
  pi.on("turn_end", (event) =>
    event.toolResults.length > 0
      ? { entries: [...event.entries, { type: "context_edit", targetId: "5eed0001", replacement: { content: "APPROVED_LATE_SOURCE" } }] }
      : undefined);
}
